            component = []
            seeds = []

            while stack:
                y, x = stack.pop()
                component.append((y, x))
                if grid[y][x] not in (0, 1):
                    seeds.append((y, x, grid[y][x]))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if not seeds:
                continue

            for y, x in component:
                if grid[y][x] != 1:
                    continue
                if not all(
                    0 <= y + dy < h and 0 <= x + dx < w and
                    grid[y + dy][x + dx] != 0
                    for dy in (-1, 0, 1)
                    for dx in (-1, 0, 1)
                ):
                    continue

                _, _, color = min(
                    seeds,
                    key=lambda seed: (abs(y - seed[0]) + abs(x - seed[1]))
                )
                out[y][x] = color

    return out
